    row_count NUMBER := 0;
    batch_size NUMBER := 10;
    case_executed VARCHAR2(20);
BEGIN
    -- Process based on threshold value
    IF threshold < 3 THEN
        case_executed := 'FIRST';
        FOR r IN (
            SELECT "ResID", "ResName", "Address" 
            FROM "Restaurant" 
            WHERE "ResID" < arg1 AND "ResName" LIKE arg2
        ) LOOP
            row_count := row_count + 1;

            IF r."ResID" > 25 THEN
                UPDATE "Restaurant" SET "ResName" = 'PROMOTED' WHERE "ResID" = r."ResID";
            ELSIF r."Address" = arg3 THEN
                DECLARE
                    visit_count NUMBER;
                BEGIN
                    SELECT COUNT(*) INTO visit_count 
                    FROM "Visits_Restaurant" vr
                    JOIN "Student" s ON vr."StuID" = s."StuID"
                    WHERE vr."ResID" = r."ResID" AND s."LName" = arg5;

                    IF visit_count > 0 THEN
                        UPDATE "Restaurant" SET "Address" = 'RETAINED' WHERE "ResID" = r."ResID";
                    ELSE
                        DELETE FROM "Visits_Restaurant" WHERE "ResID" = r."ResID";
                        DELETE FROM "Type_Of_Restaurant" WHERE "ResID" = r."ResID";
                        DELETE FROM "Restaurant" WHERE "ResID" = r."ResID";
                    END IF;
                END;
            ELSE
                UPDATE "Restaurant" 
                SET "Address" = 'PENDING', "Rating" = arg6
                WHERE "ResID" = r."ResID";
            END IF;

            IF row_count >= batch_size THEN
                batch_size := batch_size + 5;
            END IF;
        END LOOP;

    ELSIF threshold < 8 THEN
        case_executed := 'FIRST';
        FOR s IN (
            SELECT "StuID", "LName" 
            FROM "Student" 
            WHERE "StuID" BETWEEN arg4 - 5 AND arg4 + 15
        ) LOOP
            row_count := row_count + 1;

            IF s."LName" = arg5 THEN
                UPDATE "Student" SET "Major" = 700 WHERE "StuID" = s."StuID";
            END IF;

            IF s."LName" LIKE 'ACTIVE%' THEN
                UPDATE "Student" SET "LName" = 'PROCESSED' WHERE "StuID" = s."StuID";
            ELSIF s."StuID" > arg4 + 5 THEN
                threshold := threshold + s."StuID";
            ELSIF s."LName" = 'EXPIRED' THEN
                DELETE FROM "Student" WHERE "StuID" = s."StuID";
            END IF;

            IF row_count >= batch_size THEN
                batch_size := batch_size + 5;
            END IF;
        END LOOP;

    ELSIF threshold < 18 THEN
        case_executed := 'FIRST';
        FOR t IN (
            SELECT "ResTypeID" 
            FROM "Restaurant_Type" 
            WHERE "ResTypeID" > arg6 - 20
        ) LOOP
            row_count := row_count + 1;

