        UPDATE "Restaurant" SET "Address" = 'ARCHIVED' 
        WHERE "ResID" < arg1 AND "ResName" <> arg2;
        -- Force NO_DATA_FOUND error
        DECLARE
            unused NUMBER;
        BEGIN
            SELECT 1 INTO unused FROM DUAL WHERE 1 = 0;
